-- =====================================================================
-- SEO Thin Content — Расширение текстов до 300-500 слов
-- Добавляет четвёртый абзац к каждому additional_text.
-- =====================================================================

-- 1) Финансовая магия (+абзац о форматах работы)
UPDATE pages SET blocks = JSON_SET(blocks, '$.additional_text',
  CONCAT(JSON_UNQUOTE(JSON_EXTRACT(blocks,'$.additional_text')),
'\n\nРабота с финансовой энергией ведётся в удобном для вас формате — лично, по телефону или дистанционно по фотографии. Дистанционные сеансы по силе ничем не уступают очным: тонкий мир не знает географических границ. Все обращения остаются строго конфиденциальными, а после завершения работы специалист подробно объясняет, какие изменения и в какие сроки можно ожидать. Это честный, ответственный подход — без обещаний «миллион завтра», но с реальной поддержкой и заметными результатами в течение нескольких недель.'
)) WHERE page_slug = 'service-finansovaya-magiya';

-- 2) Любовная магия (+абзац об этике и ответственности)
UPDATE pages SET blocks = JSON_SET(blocks, '$.additional_text',
  CONCAT(JSON_UNQUOTE(JSON_EXTRACT(blocks,'$.additional_text')),
'\n\nОчень важно понимать: грамотная работа в сфере любви — это всегда вопрос этики. Опытный специалист никогда не возьмётся за работу, которая грубо нарушает свободную волю другого человека или может навредить ребёнку в паре. Если ваш партнёр действительно ваш по судьбе, тонкая работа лишь поможет снять преграды и услышать друг друга заново. Если же связь была изначально чужой — мастер честно скажет об этом и предложит другой путь: освобождение, исцеление и встречу с тем, кто предназначен именно вам.'
)) WHERE page_slug = 'service-lyubovnaya-magiya';

-- 3) Магия жизни (+абзац о длительности и поддержке)
UPDATE pages SET blocks = JSON_SET(blocks, '$.additional_text',
  CONCAT(JSON_UNQUOTE(JSON_EXTRACT(blocks,'$.additional_text')),
'\n\nГлубокая работа с судьбой — это не «волшебная палочка», а процесс, в котором клиент остаётся активным участником. Специалист открывает дорогу, но идти по ней предстоит вам самим: принимать решения, делать выборы, отпускать то, что больше не нужно. Между сеансами мастер остаётся на связи, отвечает на возникающие вопросы и при необходимости корректирует работу. Такой формат сопровождения даёт устойчивый результат: изменения закрепляются не на месяц-два, а на годы вперёд, постепенно перестраивая всю канву жизни.'
)) WHERE page_slug = 'service-magiya-zhizni';

-- 4) Магическая защита (+абзац о профилактике и обучении)
UPDATE pages SET blocks = JSON_SET(blocks, '$.additional_text',
  CONCAT(JSON_UNQUOTE(JSON_EXTRACT(blocks,'$.additional_text')),
'\n\nОтдельное внимание специалист уделяет профилактике: учит распознавать первые признаки чужого влияния, объясняет, какие простые ритуалы можно проводить самостоятельно, как использовать защитные обереги, соль, свечи и молитвы. Эти повседневные практики не заменяют профессиональную работу, но прекрасно её дополняют — особенно после плотного контакта с большим количеством людей, после конфликтов или возвращения из «тяжёлых» мест. Защита становится не разовой акцией, а здоровой привычкой, благодаря которой негатив перестаёт находить лазейки в вашу жизнь.'
)) WHERE page_slug = 'service-magicheskaya-zashchita';

-- 5) Порча (+абзац о реабилитации после снятия)
UPDATE pages SET blocks = JSON_SET(blocks, '$.additional_text',
  CONCAT(JSON_UNQUOTE(JSON_EXTRACT(blocks,'$.additional_text')),
'\n\nПосле снятия порчи начинается важный этап восстановления. В первые дни возможна повышенная утомляемость, эмоциональные «откаты», необычные сны — это естественная реакция тела и психики на освобождение. Специалист сопровождает клиента и в этот период: даёт рекомендации по питанию, сну, общению, простым очищающим практикам. Постепенно возвращаются силы, нормализуется самочувствие, налаживаются дела. Параллельно ставится индивидуальная защита, чтобы повторная атака стала невозможной. В результате человек получает не просто «лекарство от симптома», а долговременную устойчивость и душевный покой.'
)) WHERE page_slug = 'topic-porcha';

-- 6) Проклятие (+абзац о ребёнке/роде)
UPDATE pages SET blocks = JSON_SET(blocks, '$.additional_text',
  CONCAT(JSON_UNQUOTE(JSON_EXTRACT(blocks,'$.additional_text')),
'\n\nОсобенно важна такая работа для родителей и тех, кто только планирует ребёнка. Невостребованная родовая программа неизбежно перейдёт по линии — и ваш ребёнок окажется в той же ловушке, в которой годами бились вы. Снимая проклятие при жизни, человек буквально освобождает следующие поколения от груза, который должен был достаться им «по наследству». Этот шаг — один из самых благородных и далеко идущих в эзотерической практике, и многие клиенты отмечают, что именно желание защитить детей стало решающим в обращении к специалисту.'
)) WHERE page_slug = 'topic-proklyatie';

-- 7) Сглаз (+абзац о детях и животных)
UPDATE pages SET blocks = JSON_SET(blocks, '$.additional_text',
  CONCAT(JSON_UNQUOTE(JSON_EXTRACT(blocks,'$.additional_text')),
'\n\nОсобого внимания заслуживает сглаз у детей и домашних животных: они наиболее уязвимы к чужой энергетике, потому что ещё не имеют сформированной защиты. У ребёнка сглаз проявляется внезапной плаксивостью, отказом от еды, нарушением сна, у животного — апатией, болезнями без причин. В этих случаях специалист использует мягкие, щадящие методики — выкатывание яйцом, заговорённую воду, простые материнские молитвы, которым может научиться сама мама. Снятие проходит быстро и без побочных эффектов, а атмосфера в доме почти сразу становится спокойнее и теплее.'
)) WHERE page_slug = 'topic-sglaz';

-- 8) Венец безбрачия (+абзац о формате и ожидании)
UPDATE pages SET blocks = JSON_SET(blocks, '$.additional_text',
  CONCAT(JSON_UNQUOTE(JSON_EXTRACT(blocks,'$.additional_text')),
'\n\nПосле снятия венца события обычно начинают разворачиваться не мгновенно, а постепенно: ослабевают старые «застрявшие» связи, отпадают неподходящие партнёры, появляются новые знакомства — часто в неожиданных местах и обстоятельствах. Важно дать процессу время и не пытаться форсировать встречу искусственно. Специалист даёт практические рекомендации: какие места посещать, как работать со своим женским или мужским образом, что менять во внешнем виде и привычках. Такой комплексный подход помогает не просто «снять программу», а перестроить всю личную сферу под здоровый, долговременный союз.'
)) WHERE page_slug = 'topic-venets-bezbrachiya';

-- 9) Приворот (+абзац о признаках для близких)
UPDATE pages SET blocks = JSON_SET(blocks, '$.additional_text',
  CONCAT(JSON_UNQUOTE(JSON_EXTRACT(blocks,'$.additional_text')),
'\n\nЕсли вы подозреваете, что под привороты попал близкий человек — сын, дочь, брат, друг, — действовать стоит особенно деликатно. Прямые обвинения и попытки «открыть глаза» обычно вызывают только агрессию: жертва приворота воспринимает партнёра как «свет в окошке» и любую критику отметает. Намного эффективнее обратиться к специалисту самостоятельно: грамотный мастер может работать с фотографией и согласием самого клиента (родственника), мягко ослабляя привязку. Постепенно человек начинает «приходить в себя» и сам видит ситуацию без розовых очков — и тогда у него появляется шанс на честный выбор.'
)) WHERE page_slug = 'topic-privorot';

-- 10) Заклятие (+абзац про слова и внимание к речи)
UPDATE pages SET blocks = JSON_SET(blocks, '$.additional_text',
  CONCAT(JSON_UNQUOTE(JSON_EXTRACT(blocks,'$.additional_text')),
'\n\nОтдельное внимание после снятия заклятия специалист уделяет работе с собственной речью клиента. Многие фразы, которые мы повторяем годами в адрес себя или близких («у меня никогда не получится», «вечно мне не везёт», «лучше бы я не родился»), сами по себе формируют новые программы. Мастер показывает, как заменить эти автоматические клише на нейтральные или поддерживающие конструкции, как обращаться со словами в моменты сильных эмоций. Эта внутренняя гигиена речи — лучшая профилактика того, чтобы старые программы не вернулись и не появились новые.'
)) WHERE page_slug = 'topic-zaklyatie';

SELECT page_slug,
       CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(blocks, '$.additional_text'))) AS chars,
       (CHAR_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(blocks, '$.additional_text'))) -
        CHAR_LENGTH(REPLACE(JSON_UNQUOTE(JSON_EXTRACT(blocks, '$.additional_text')), ' ', '')) + 1) AS words_approx
FROM pages
WHERE page_slug LIKE 'service-%' OR page_slug LIKE 'topic-%'
ORDER BY page_slug;
